def json_safe(value: Any, depth: int = 0) -> Any:
    if depth > 12:
        return str(value)
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, (list, tuple, set)):
        return [json_safe(item, depth + 1) for item in value]
    if isinstance(value, dict):
        return {str(key): json_safe(item, depth + 1) for key, item in value.items()}
    if hasattr(value, "model_dump"):
        try:
            return json_safe(value.model_dump(), depth + 1)
        except Exception:
            pass
    if hasattr(value, "dict"):
        try:
            return json_safe(value.dict(), depth + 1)
        except Exception:
            pass
    if hasattr(value, "__dict__"):
        try:
            return json_safe({key: item for key, item in value.__dict__.items() if not key.startswith("_")}, depth + 1)
        except Exception:
            pass
    return str(value)


def compact_json(value: Any) -> str:
    return json.dumps(json_safe(value), ensure_ascii=False, separators=(",", ":"))


def model_to_dict(value: Any) -> Dict[str, Any]:
    if hasattr(value, "model_dump"):
        data = value.model_dump(exclude_none=True)
    elif hasattr(value, "dict"):
        data = value.dict(exclude_none=True)
    elif isinstance(value, dict):
        data = value
    else:
        data = {}
    return dict(data)


def content_to_text(content: Any) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: List[str] = []
        for item in content:
            if isinstance(item, dict):
                item_type = str(item.get("type", "")).strip().lower()
                if item_type == "text" and item.get("text") is not None:
                    parts.append(str(item.get("text")))
                elif item.get("content") is not None:
                    parts.append(content_to_text(item.get("content")))
                else:
                    parts.append(compact_json(item))
            else:
                parts.append(content_to_text(item))
        return "\n".join(part for part in parts if part)
    return compact_json(content)


def normalize_messages(messages: List[Any]) -> List[Dict[str, str]]:
    normalized: List[Dict[str, str]] = []
    for message in messages:
        data = model_to_dict(message)
        role = str(data.get("role", "user")).strip().lower()
        if role == "developer":
            role = "system"
        if role not in {"system", "user", "assistant"}:
            role = "user"
        content = content_to_text(data.get("content", ""))
        normalized.append({"role": role, "content": content})
    return normalized


def normalize_domain(domain: Any) -> Optional[str]:
    if domain is None:
        return None
    text = str(domain).strip().lower()
    if not text:
        return None
    text = re.sub(r"^https?://", "", text)
    text = text.split("/")[0]
    text = text.split("?")[0]
    text = text.split("#")[0]
    text = text.strip().strip(".")
    if text.startswith("www."):
        text = text[4:]
    if not re.fullmatch(r"[a-z0-9][a-z0-9.-]*\.[a-z]{2,63}", text):
        return None
    if ".." in text:
        return None
    return text


def normalize_domains(value: Any) -> List[str]:
    raw_items: List[Any]
    if value is None:
        raw_items = []
    elif isinstance(value, str):
        raw_items = [item.strip() for item in value.split(",")]
    elif isinstance(value, list):
        raw_items = value
    else:
        raw_items = []
    domains: List[str] = []
    seen: Set[str] = set()
    for item in raw_items:
        domain = normalize_domain(item)
        if domain and domain not in seen:
            seen.add(domain)
            domains.append(domain)
    return domains


def normalize_search_type(value: Any) -> str:
    text = str(value or "auto").strip().lower()
    text = text.replace("_", "-")
    text = re.sub(r"\s+", "-", text)
    if text in {"deeplite", "deep-lite"}:
        return "deep-lite"
    if text in {"deepreasoning", "deep-reasoning"}:
        return "deep-reasoning"
    if text not in ALLOWED_SEARCH_TYPES:
        return "auto"
    return text


def normalize_search_spec(raw: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(raw, dict):
        return None
    query = str(raw.get("query", "")).strip()
    if not query:
        return None
    search_type = normalize_search_type(raw.get("type", raw.get("search_type", "auto")))
    summary_query = str(raw.get("summary_query", raw.get("summaryQuery", raw.get("summary", query)))).strip()
    if not summary_query:
        summary_query = query
    include_domains = normalize_domains(raw.get("include_domains", raw.get("includeDomains", [])))
    exclude_domains = normalize_domains(raw.get("exclude_domains", raw.get("excludeDomains", [])))
    include_set = set(include_domains)
    exclude_domains = [domain for domain in exclude_domains if domain not in include_set]
    return {
        "query": query,
        "type": search_type,
        "summary_query": summary_query,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
    }


def search_signature(spec: Dict[str, Any]) -> Tuple[Any, ...]:
    return (
        spec.get("query", ""),
        spec.get("type", ""),
        spec.get("summary_query", ""),
        tuple(spec.get("include_domains", [])),
        tuple(spec.get("exclude_domains", [])),
    )


def extract_json_object(text: str) -> Dict[str, Any]:
    cleaned = str(text or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json|JSON)?\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned).strip()
    try:
        parsed = json.loads(cleaned)
        if isinstance(parsed, dict):
            return parsed
        raise ValueError("JSON root must be an object")
    except json.JSONDecodeError:
        pass
    start = cleaned.find("{")
    if start < 0:
        raise ValueError("No JSON object found")
    in_string = False
    escaped = False
    depth = 0
    for index in range(start, len(cleaned)):
        char = cleaned[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == "\"":
                in_string = False
        else:
            if char == "\"":
                in_string = True
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    parsed = json.loads(cleaned[start:index + 1])
                    if isinstance(parsed, dict):
                        return parsed
                    raise ValueError("JSON root must be an object")
    raise ValueError("No complete JSON object found")


