async def get_search_decision(model: str, messages: List[Dict[str, str]], search_history: List[Dict[str, Any]]) -> Dict[str, Any]:
    planner_messages = build_planner_messages(messages, search_history)
    result = await openai_chat(model, planner_messages, 0.0)
    content = result["content"]
    try:
        decision = extract_json_object(content)
    except Exception as first_error:
        repair_messages = [
            {"role": "system", "content": "Return only valid JSON matching the required schema. Do not use markdown. Do not add explanations."},
            {"role": "user", "content": "Invalid JSON was returned. Error: " + str(first_error) + "\nPrevious output:\n" + content + "\nRequired schemas:\n{\"action\":\"answer\",\"searches\":[]}\n{\"action\":\"search\",\"searches\":[{\"query\":\"...\",\"type\":\"auto\",\"summary_query\":\"...\",\"include_domains\":[],\"exclude_domains\":[]}]}"},
        ]
        repaired = await openai_chat(model, repair_messages, 0.0)
        try:
            decision = extract_json_object(repaired["content"])
        except Exception:
            decision = {"action": "answer", "searches": []}
    action = str(decision.get("action", "answer")).strip().lower()
    if action != "search":
        return {"action": "answer", "searches": []}
    searches_raw = decision.get("searches", [])
    if not isinstance(searches_raw, list):
        searches_raw = []
    searches: List[Dict[str, Any]] = []
    for item in searches_raw:
        spec = normalize_search_spec(item)
        if spec is not None:
            searches.append(spec)
    if not searches:
        return {"action": "answer", "searches": []}
    return {"action": "search", "searches": searches}


def get_any_value(item: Any, names: List[str]) -> Any:
    for name in names:
        if isinstance(item, dict) and name in item:
            return item.get(name)
        if hasattr(item, name):
            try:
                return getattr(item, name)
            except Exception:
                pass
    return None


def normalize_exa_result(item: Any) -> Dict[str, Any]:
    result_item: Dict[str, Any] = {}
    field_names = {
        "title": ["title"],
        "url": ["url"],
        "id": ["id"],
        "author": ["author"],
        "score": ["score"],
        "published_date": ["published_date", "publishedDate"],
        "summary": ["summary"],
        "image": ["image"],
        "favicon": ["favicon"],
    }
    for output_key, possible_keys in field_names.items():
        value = get_any_value(item, possible_keys)
        if value is not None:
            result_item[output_key] = json_safe(value)
    raw_item = json_safe(item)
    if isinstance(raw_item, dict):
        for key, value in raw_item.items():
            if key not in result_item and value is not None and key in {"text", "highlights", "highlight_scores", "subpages", "extras"}:
                result_item[key] = value
    return result_item


def exa_search_sync(spec: Dict[str, Any], round_number: int, index: int) -> Dict[str, Any]:
    started = time.time()
    kwargs: Dict[str, Any] = {
        "num_results": NUM_EXA_RESULTS,
        "type": spec["type"],
        "contents": {
            "summary": {
                "query": spec["summary_query"],
            }
        },
    }
    if spec["include_domains"]:
        kwargs["include_domains"] = spec["include_domains"]
    if spec["exclude_domains"]:
        kwargs["exclude_domains"] = spec["exclude_domains"]
    raw = exa.search(spec["query"], **kwargs)
    data = json_safe(raw)
    if isinstance(data, dict):
        raw_results = data.get("results", [])
    else:
        raw_results = []
    if not isinstance(raw_results, list):
        raw_results = []
    results = [normalize_exa_result(item) for item in raw_results]
    record: Dict[str, Any] = {
        "round": round_number,
        "index": index,
        "query": spec["query"],
        "type": spec["type"],
        "summary_query": spec["summary_query"],
        "include_domains": spec["include_domains"],
        "exclude_domains": spec["exclude_domains"],
        "num_results": NUM_EXA_RESULTS,
        "elapsed_ms": int((time.time() - started) * 1000),
        "results_returned": len(results),
        "results": results,
    }
    if isinstance(data, dict):
        for key, value in data.items():
            if key not in {"results"} and value is not None:
                record[key] = value
    return record


async def execute_searches(searches: List[Dict[str, Any]], round_number: int, request: Request) -> List[Dict[str, Any]]:
    semaphore = asyncio.Semaphore(SEARCH_CONCURRENCY)

    async def run_one(index: int, spec: Dict[str, Any]) -> Dict[str, Any]:
        async with semaphore:
            if await request.is_disconnected():
                raise HTTPException(status_code=499, detail="Client disconnected")
            try:
                return await asyncio.wait_for(asyncio.to_thread(exa_search_sync, spec, round_number, index), timeout=EXA_TIMEOUT_SECONDS)
            except HTTPException:
                raise
            except Exception as error:
                return {
                    "round": round_number,
                    "index": index,
                    "query": spec.get("query", ""),
                    "type": spec.get("type", "auto"),
                    "summary_query": spec.get("summary_query", spec.get("query", "")),
                    "include_domains": spec.get("include_domains", []),
                    "exclude_domains": spec.get("exclude_domains", []),
                    "num_results": NUM_EXA_RESULTS,
                    "error": error.__class__.__name__ + ": " + str(error),
                    "results_returned": 0,
                    "results": [],
                }

    tasks = [run_one(index + 1, spec) for index, spec in enumerate(searches)]
    return await asyncio.gather(*tasks)


