async def generate_final_answer(chat_request: ChatRequest, messages: List[Dict[str, str]], search_history: List[Dict[str, Any]]) -> Dict[str, Any]:
    model = (chat_request.model or REQUESTY_MODEL).strip()
    temperature = REQUESTY_TEMPERATURE if chat_request.temperature is None else float(chat_request.temperature)
    if temperature < 0:
        raise HTTPException(status_code=400, detail="temperature must be greater than or equal to 0")
    result = await openai_chat(model, build_final_messages(messages, search_history), temperature)
    return result


async def run_agent(chat_request: ChatRequest, request: Request) -> Dict[str, Any]:
    messages = normalize_messages(chat_request.messages)
    if not messages:
        raise HTTPException(status_code=400, detail="messages must contain at least one message")
    model = (chat_request.model or REQUESTY_MODEL).strip()
    search_history: List[Dict[str, Any]] = []
    debug_decisions: List[Dict[str, Any]] = []
    seen_searches: Set[Tuple[Any, ...]] = set()
    if chat_request.web_search is not False:
        rounds_completed = 0
        while True:
            if await request.is_disconnected():
                raise HTTPException(status_code=499, detail="Client disconnected")
            decision = await get_search_decision(model, messages, search_history)
            if chat_request.debug:
                debug_decisions.append(decision)
            if decision.get("action") != "search":
                break
            planned_searches = decision.get("searches", [])
            if not isinstance(planned_searches, list):
                break
            searches_to_run: List[Dict[str, Any]] = []
            for spec in planned_searches:
                normalized = normalize_search_spec(spec)
                if normalized is None:
                    continue
                signature = search_signature(normalized)
                if signature in seen_searches:
                    continue
                seen_searches.add(signature)
                searches_to_run.append(normalized)
            if not searches_to_run:
                break
            rounds_completed += 1
            records = await execute_searches(searches_to_run, rounds_completed, request)
            search_history.extend(records)
    final_result = await generate_final_answer(chat_request, messages, search_history)
    response: Dict[str, Any] = {
        "id": "chatcmpl_" + uuid.uuid4().hex,
        "object": "chat.completion",
        "created": int(time.time()),
        "model": model,
        "role": "assistant",
        "content": final_result.get("content", ""),
        "finish_reason": final_result.get("finish_reason"),
        "usage": final_result.get("usage"),
        "searches": search_history,
        "search_rounds": len({record.get("round") for record in search_history}),
        "search_count": len(search_history),
        "max_tokens": MODEL_MAX_TOKENS,
        "reasoning_effort": REASONING_EFFORT,
    }
    if chat_request.debug:
        response["debug_decisions"] = debug_decisions
    return response


