@app.post("/v1/chat/completions")
async def v1_chat_completions(body: Dict[str, Any], request: Request) -> Dict[str, Any]:
    messages = body.get("messages")
    if not isinstance(messages, list):
        raise HTTPException(status_code=400, detail="messages must be a list")
    chat_request = ChatRequest(
        messages=[ChatMessage(**message) if isinstance(message, dict) else ChatMessage(role="user", content=str(message)) for message in messages],
        model=body.get("model"),
        temperature=body.get("temperature"),
        max_tokens=body.get("max_tokens"),
        reasoning_effort=body.get("reasoning_effort"),
        web_search=body.get("web_search", True),
        debug=body.get("debug", False),
    )
    result = await run_agent(chat_request, request)
    return {
        "id": result["id"],
        "object": "chat.completion",
        "created": result["created"],
        "model": result["model"],
        "choices": [
            {
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": result["content"],
                },
                "finish_reason": result.get("finish_reason") or "stop",
            }
        ],
        "usage": result.get("usage"),
